SELECT id, entry_signal_id, symbol, stop_loss_usdt, take_profit_usdt, highest_price_usdt, profit_lock_active, profit_lock_price_usdt, profit_lock_progress_percent, profit_lock_state, profit_lock_activated_at, UNIX_TIMESTAMP(profit_lock_activated_at) AS pl_epoch, entry_stage, allocated_position_percent, entry_quality_score, near_tp_state, near_tp_harvest_used, status, opened_at, updated_at FROM crypto_ai.wallet_managed_position WHERE entry_signal_id IN (156723,159408,165412,167668,171589,176710) ORDER BY id;